case 'materials':require_role('supply','admin');$q=trim((string)($_GET['q']??''));$s=db()->prepare('SELECT m.*,c.name category_name FROM materials m LEFT JOIN categories c ON c.id=m.category_id WHERE (m.name LIKE ? OR m.code LIKE ?) ORDER BY m.active DESC,m.name');$s->execute(["%$q%","%$q%"]);$rows=$s->fetchAll();$cats=db()->query('SELECT * FROM categories WHERE active=1 ORDER BY name')->fetchAll();page_start('คลังวัสดุและรับเข้า','ยอดคงเหลือแก้ตรงจากทะเบียนไม่ได้');?><div class="toolbar"><form class="search"><input name="q" value="<?=h($q)?>" placeholder="ค้นหารหัสหรือชื่อ"><button class="btn secondary">ค้นหา</button></form><button class="btn primary" data-dialog="material-dialog">+ เพิ่มวัสดุ</button></div><section class="card"><?php table_materials($rows);?></section><section class="card"><h2>รับเข้า / บันทึกยอดตั้งต้น</h2><form method="post" class="form-grid"><?php csrf_field();?><input type="hidden" name="action" value="receive_stock"><label>วัสดุ<select name="material_id" required><?php options_material($rows);?></select></label><label>จำนวนหน่วยพื้นฐาน<input type="number" name="quantity" min=".001" step=".001" required><small>หากซื้อเป็นแพ็ก ให้แปลงเป็นหน่วยพื้นฐานก่อน</small></label><label>วันที่<input type="date" name="received_date" value="<?=date('Y-m-d')?>" required></label><label>แหล่งที่มา<input name="source" required></label><label>เอกสารอ้างอิง<input name="reference_no"></label><label class="check"><input type="checkbox" name="opening"> ยอดตั้งต้นจากการนับจริง</label><button class="btn primary">บันทึกรับเข้า</button></form></section><dialog id="material-dialog"><form method="post" enctype="multipart/form-data"><?php csrf_field();?><input type="hidden" name="action" value="material_save"><h2>เพิ่มวัสดุ</h2><div class="form-grid"><label>รหัส<input name="code" required></label><label>ชื่อ<input name="name" required></label><label>หมวดหมู่<select name="category_id"><?php foreach($cats as$c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></label><label>หน่วยพื้นฐาน<input name="unit" placeholder="รีม / ด้าม / ม้วน" required></label><label>ยอดขั้นต่ำ<input type="number" name="minimum_qty" min="0" step=".001" value="0"></label><label>ตำแหน่ง<input name="location"></label><label>รูปภาพ (JPEG/PNG/WebP ไม่เกิน 2 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="wide">รายละเอียด<textarea name="description"></textarea></label><label class="check"><input type="checkbox" name="active" checked> เปิดให้เบิก</label><label class="check"><input type="checkbox" name="track_assignee"> ติดตามผู้รับไปใช้</label></div><div class="actions"><button class="btn primary">บันทึก</button><button type="button" class="btn secondary" data-close>ปิด</button></div></form></dialog><?php page_end();break;

case 'material_import':require_role('supply','admin');page_start('นำเข้าทะเบียนวัสดุ','เพิ่มรายการใหม่หรือปรับปรุงรายการเดิมโดยเทียบรหัสวัสดุ');?><section class="card"><h2>นำเข้าจาก CSV UTF-8</h2><div class="notice"><b>สำคัญ:</b> การนำเข้าแก้เฉพาะทะเบียน ไม่แก้ยอดคงเหลือโดยตรง หากต้องการเพิ่มยอดให้ใช้เมนูรับเข้า/ยอดตั้งต้นเพื่อสร้าง Stock Movement</div><ol><li><a href="material-template.php">ดาวน์โหลดไฟล์แม่แบบ CSV</a></li><li>แก้ข้อมูลด้วย Excel แล้วบันทึกเป็น <b>CSV UTF-8 (Comma delimited)</b></li><li>รหัสใหม่จะถูกเพิ่ม รหัสที่มีอยู่จะถูกปรับปรุง โดยยังรักษายอดและประวัติเดิม</li></ol><form method="post" enctype="multipart/form-data"><?php csrf_field();?><input type="hidden" name="action" value="material_import"><label>ไฟล์ CSV ไม่เกิน 2 MB<input type="file" name="csv" accept=".csv,text/csv" required></label><button class="btn primary" data-confirm="ยืนยันนำเข้าทะเบียนวัสดุ?">นำเข้าข้อมูล</button> <a class="btn secondary" href="?page=materials">กลับคลังวัสดุ</a></form></section><section class="card"><h2>คอลัมน์ในแม่แบบ</h2><div class="table-wrap"><table><thead><tr><th>คอลัมน์</th><th>ความหมาย</th></tr></thead><tbody><tr><td>code</td><td>รหัสไม่ซ้ำ ใช้เป็นกุญแจเพิ่ม/ปรับปรุง</td></tr><tr><td>name, category, unit</td><td>ชื่อ หมวดหมู่ และหน่วยพื้นฐาน</td></tr><tr><td>minimum_qty</td><td>ยอดขั้นต่ำ ตั้งแต่ 0</td></tr><tr><td>location, description</td><td>ตำแหน่งและรายละเอียด</td></tr><tr><td>active</td><td>1 เปิดเบิก, 0 ปิดใช้งาน</td></tr><tr><td>track_assignee</td><td>1 ติดตามผู้รับ, 0 ไม่ติดตาม</td></tr></tbody></table></div></section><?php page_end();break;

case 'material_edit':require_role('supply','admin');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM materials WHERE id=?');$s->execute([$id]);$m=$s->fetch();if(!$m)not_found();$cats=db()->query('SELECT * FROM categories WHERE active=1 ORDER BY name')->fetchAll();page_start('แก้ไขวัสดุ '.$m['code'],'ยอดคงเหลือเปลี่ยนได้ผ่านรับเข้า จ่าย คืน ยอดตั้งต้น หรือตรวจนับเท่านั้น');?><section class="card"><form method="post" enctype="multipart/form-data" class="form-grid"><?php csrf_field();?><input type="hidden" name="action" value="material_save"><input type="hidden" name="id" value="<?=$id?>"><label>รหัส<input name="code" value="<?=h($m['code'])?>" required></label><label>ชื่อ<input name="name" value="<?=h($m['name'])?>" required></label><label>หมวดหมู่<select name="category_id"><?php foreach($cats as$c):?><option value="<?=$c['id']?>" <?=$c['id']==$m['category_id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label>หน่วยพื้นฐาน<input name="unit" value="<?=h($m['unit'])?>" required></label><label>ยอดขั้นต่ำ<input type="number" name="minimum_qty" min="0" step=".001" value="<?=h($m['minimum_qty'])?>"></label><label>ตำแหน่ง<input name="location" value="<?=h($m['location'])?>"></label><label>เปลี่ยนรูป<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><?php if($m['image_path']):?><a href="file.php?material=<?=$id?>" target="_blank">ดูรูปปัจจุบัน</a><?php endif;?></label><label class="wide">รายละเอียด<textarea name="description"><?=h($m['description'])?></textarea></label><label class="check"><input type="checkbox" name="active" <?=$m['active']?'checked':''?>> เปิดให้เบิก</label><label class="check"><input type="checkbox" name="track_assignee" <?=$m['track_assignee']?'checked':''?>> ติดตามผู้รับไปใช้</label><button class="btn primary">บันทึกการแก้ไข</button></form></section><?php page_end();break;

