case 'confirm_receipts':
    require_role('requester');$s=db()->prepare('SELECT i.id,i.issue_no,i.issued_at,i.receiver_name,r.id requisition_id,r.request_no,r.completed_at,rc.confirmed_at,(SELECT COUNT(*) FROM issue_items ii WHERE ii.issue_id=i.id) item_count FROM issues i JOIN requisitions r ON r.id=i.requisition_id LEFT JOIN receipts_confirmation rc ON rc.issue_id=i.id WHERE r.requester_id=? ORDER BY rc.confirmed_at IS NULL DESC,i.issued_at DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();$pending=array_filter($rows,fn($row)=>empty($row['confirmed_at']));
    page_start('ยืนยันรับของ','ตรวจสอบรายการที่ได้รับแล้วกดยืนยัน คำขอจะเสร็จสมบูรณ์เมื่อยืนยันครบทุกใบจ่าย');?>
    <div class="receipt-summary"><span class="receipt-summary-icon"><?=ui_icon($pending?'bell':'check')?></span><div><strong><?=$pending?count($pending).' รายการรอการยืนยัน':'ยืนยันรับของครบแล้ว'?></strong><p><?=$pending?'การยืนยันไม่ตัดสต๊อกซ้ำ และช่วยปิดคำขอให้เสร็จสมบูรณ์':'ขณะนี้ไม่มีรายการจ่ายที่ต้องดำเนินการ'?></p></div></div>
