case 'user_edit':require_role('admin');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$x=$s->fetch();if(!$x)not_found();$s=db()->prepare('SELECT r.code FROM roles r JOIN user_roles ur ON ur.role_id=r.id WHERE ur.user_id=?');$s->execute([$id]);$assigned=$s->fetchAll(PDO::FETCH_COLUMN);$groups=db()->query('SELECT * FROM work_groups ORDER BY name')->fetchAll();$roles=db()->query('SELECT * FROM roles')->fetchAll();page_start('แก้ไขบัญชี '.$x['username'],'บัญชีที่มีประวัติให้ปิดใช้งานแทนการลบ');?><section class="card"><form method="post" class="form-grid"><?php csrf_field();?><input type="hidden" name="action" value="user_save"><input type="hidden" name="id" value="<?=$id?>"><label>ชื่อผู้ใช้<input name="username" value="<?=h($x['username'])?>" required></label><label>ชื่อ-สกุล<input name="full_name" value="<?=h($x['full_name'])?>" required></label><label>รหัสผ่านใหม่ (เว้นว่างเพื่อคงเดิม)<input type="password" name="password" minlength="6"><small>หากเปลี่ยน ต้องมีอย่างน้อย 6 ตัวอักษร</small></label><label>กลุ่มงาน<select name="work_group_id"><option value="">-</option><?php foreach($groups as$g):?><option value="<?=$g['id']?>" <?=$g['id']==$x['work_group_id']?'selected':''?>><?=h($g['name'])?></option><?php endforeach;?></select></label><label>LINE User ID ของผู้ใช้<input name="line_user_id" maxlength="33" value="<?=h($x['line_user_id']??'')?>" placeholder="Uxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"><small>ใช้แจ้งผลอนุมัติ ส่งกลับ ไม่อนุมัติ และจ่ายวัสดุ</small></label><fieldset><legend>บทบาท</legend><?php foreach($roles as$r):?><label class="check"><input type="checkbox" name="roles[]" value="<?=h($r['code'])?>" <?=in_array($r['code'],$assigned,true)?'checked':''?>> <?=h($r['name_th'])?></label><?php endforeach;?></fieldset><label class="check"><input type="checkbox" name="active" <?=$x['active']?'checked':''?>> เปิดใช้งาน</label><button class="btn primary">บันทึกบัญชีและสิทธิ์</button></form></section><?php page_end();break;
case 'print':print_request((int)($_GET['id']??0),$u);break;
default:not_found();
