function request_line(array$m,array$l):void{$selectedItem=null;foreach($m as$x)if($x['id']==($l['material_id']??'')){$selectedItem=$x;break;}$image=$selectedItem&&!empty($selectedItem['image_path'])?'file.php?material='.(int)$selectedItem['id']:'';?><div class="request-line"><span class="request-line-number" aria-hidden="true"></span><div class="request-material-preview"><img data-material-image src="<?=h($image)?>" alt="<?=h($selectedItem?'รูป '.$selectedItem['name']:'')?>" <?=$image===''?'hidden':''?>><span data-material-placeholder <?=$image!==''?'hidden':''?>><?=ui_icon('image')?><small>ไม่มีรูป</small></span></div><label class="request-material-field"><span>วัสดุ</span><select class="material-select" name="material_id[]" required><option value="" data-stock="" data-unit="" data-image="" data-name="">เลือกวัสดุ</option><?php foreach($m as$x):$selected=$x['id']==($l['material_id']??'');$empty=(float)$x['stock_qty']<=0;?><option value="<?=$x['id']?>" data-stock="<?=h(qty($x['stock_qty']))?>" data-unit="<?=h($x['unit'])?>" data-image="<?=!empty($x['image_path'])?'file.php?material='.(int)$x['id']:''?>" data-name="<?=h($x['name'])?>" data-empty="<?=$empty?'1':'0'?>" <?=$selected?'selected':''?> <?=$empty&&!$selected?'disabled':''?>><?=h($x['code'].' · '.$x['name'].($empty?' · หมดสต๊อก — เบิกไม่ได้':' · คงเหลือ '.qty($x['stock_qty']).' '.$x['unit']))?></option><?php endforeach;?></select><small class="material-stock-hint" data-stock-hint><?=$selectedItem?((float)$selectedItem['stock_qty']>0?'พร้อมเบิก '.qty($selectedItem['stock_qty']).' '.$selectedItem['unit']:'หมดสต๊อก — กรุณาเปลี่ยนรายการ'):'เลือกวัสดุเพื่อดูยอดคงเหลือ'?></small></label><label class="request-quantity-field"><span>จำนวนที่ขอ</span><div class="quantity-control"><input type="number" name="quantity[]" min=".001" step=".001" value="<?=h($l['requested_qty']??'')?>" placeholder="0" inputmode="decimal" required><span data-unit><?=h($selectedItem['unit']??'หน่วย')?></span></div><small>กรอกเป็นหน่วยพื้นฐาน</small></label><button type="button" class="icon-btn request-remove" data-remove-line aria-label="ลบรายการ" title="ลบรายการ">×</button></div><?php }
function request_table(array$rows,bool$showUser=false):void{?><section class="card"><div class="table-wrap"><table><thead><tr><th>เลขคำขอ</th><?php if($showUser):?><th>ผู้เบิก</th><?php endif;?><th>วันที่</th><th>รายการ</th><th>สถานะ</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><a href="?page=request_view&id=<?=$r['id']?>"><?=h($r['request_no']?:'แบบร่าง #'.$r['id'])?></a></td><?php if($showUser):?><td><?=h($r['full_name'])?></td><?php endif;?><td><?=thai_date($r['submitted_at']?:$r['created_at'])?></td><td><?=h($r['item_count'])?></td><td><?=request_badge($r)?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">ไม่มีรายการ</td></tr><?php endif;?></tbody></table></div></section><?php }
function item_table(array$items):void{?><div class="table-wrap"><table><thead><tr><th>รหัส/รายการ</th><th>ขอ</th><th>อนุมัติ</th><th>จ่ายแล้ว</th></tr></thead><tbody><?php foreach($items as$i):?><tr><td><?=h($i['code'].' · '.$i['name'])?></td><td><?=qty($i['requested_qty']).' '.h($i['unit'])?></td><td><?=is_null($i['approved_qty'])?'-':qty($i['approved_qty'])?></td><td><?=qty($i['issued_qty'])?></td></tr><?php endforeach;?></tbody></table></div><?php }
function table_materials(array$rows,bool$compact=false):void{?><div class="table-wrap"><table><thead><tr><th>รหัส/รายการ</th><?php if(!$compact):?><th>หมวด</th><?php endif;?><th>คงเหลือ</th><th>ขั้นต่ำ</th><?php if(!$compact):?><th>ตำแหน่ง</th><th>สถานะ</th><?php endif;?></tr></thead><tbody><?php foreach($rows as$m):?><tr class="<?=$m['stock_qty']<=$m['minimum_qty']?'low':''?>"><td><?php if(!$compact&&has_role('supply','admin')):?><a href="?page=material_edit&id=<?=$m['id']?>"><?php endif;?><?=h($m['code'].' · '.$m['name'])?><?php if(!$compact&&has_role('supply','admin')):?></a><?php endif;?></td><?php if(!$compact):?><td><?=h($m['category_name']??'')?></td><?php endif;?><td><strong><?=qty($m['stock_qty']).' '.h($m['unit'])?></strong></td><td><?=qty($m['minimum_qty'])?></td><?php if(!$compact):?><td><?=h($m['location'])?></td><td><?=$m['active']?'เปิดเบิก':'ปิดใช้งาน'?></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">ไม่มีข้อมูล</td></tr><?php endif;?></tbody></table></div><?php }
function options_material(array$rows):void{foreach($rows as$m)if($m['active']):?><option value="<?=$m['id']?>"><?=h($m['code'].' · '.$m['name'].' ('.$m['unit'].')')?></option><?php endif;}
function report_table(string$type):void{if($type==='movements'){$rows=db()->query('SELECT sm.*,m.code,m.name,m.unit,u.full_name FROM stock_movements sm JOIN materials m ON m.id=sm.material_id JOIN users u ON u.id=sm.created_by ORDER BY sm.id DESC LIMIT 500')->fetchAll();?><h2>ประวัติการเคลื่อนไหว</h2><div class="table-wrap"><table><thead><tr><th>วันเวลา</th><th>วัสดุ</th><th>ประเภท</th><th>เปลี่ยนแปลง</th><th>คงเหลือ</th><th>อ้างอิง</th><th>ผู้บันทึก</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=thai_date($r['created_at'])?></td><td><?=h($r['name'])?></td><td><?=h($r['movement_type'])?></td><td><?=qty($r['quantity_delta'])?></td><td><?=qty($r['balance_after'])?></td><td><?=h($r['reference_no'])?></td><td><?=h($r['full_name'])?></td></tr><?php endforeach;?></tbody></table></div><?php }elseif($type==='usage'){$rows=db()->query('SELECT r.request_no,r.submitted_at,u.full_name,g.name group_name,m.name,m.unit,ri.requested_qty,ri.approved_qty,ri.issued_qty FROM requisition_items ri JOIN requisitions r ON r.id=ri.requisition_id JOIN users u ON u.id=r.requester_id LEFT JOIN work_groups g ON g.id=r.work_group_id JOIN materials m ON m.id=ri.material_id ORDER BY r.id DESC LIMIT 500')->fetchAll();?><h2>การเบิกแยกรายการ</h2><div class="table-wrap"><table><thead><tr><th>เลขคำขอ</th><th>ผู้เบิก/กลุ่ม</th><th>วัสดุ</th><th>ขอ</th><th>อนุมัติ</th><th>จ่าย</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['request_no'])?></td><td><?=h($r['full_name'].' / '.$r['group_name'])?></td><td><?=h($r['name'])?></td><td><?=qty($r['requested_qty'])?></td><td><?=qty($r['approved_qty'])?></td><td><?=qty($r['issued_qty']).' '.h($r['unit'])?></td></tr><?php endforeach;?></tbody></table></div><?php }elseif($type==='assets'){$rows=db()->query('SELECT aa.*,m.name,m.unit,u.full_name,r.request_no FROM asset_assignments aa JOIN materials m ON m.id=aa.material_id JOIN users u ON u.id=aa.assigned_user_id JOIN requisition_items ri ON ri.id=aa.requisition_item_id JOIN requisitions r ON r.id=ri.requisition_id WHERE aa.quantity>aa.returned_qty ORDER BY aa.assigned_at DESC')->fetchAll();?><h2>อุปกรณ์ใช้ซ้ำที่อยู่กับผู้ใช้</h2><div class="table-wrap"><table><thead><tr><th>ผู้รับ</th><th>วัสดุ</th><th>คงค้าง</th><th>คำขอ</th><th>วันที่</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['full_name'])?></td><td><?=h($r['name'])?></td><td><?=qty($r['quantity']-$r['returned_qty']).' '.h($r['unit'])?></td><td><?=h($r['request_no'])?></td><td><?=thai_date($r['assigned_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php }else{$rows=db()->query('SELECT m.*,c.name category_name FROM materials m LEFT JOIN categories c ON c.id=m.category_id ORDER BY m.name')->fetchAll();?><h2>ยอดคงเหลือ ณ ปัจจุบัน</h2><?php table_materials($rows);}}
function print_request(int$id,array$u):never{$s=db()->prepare('SELECT r.*,u.full_name,g.name group_name FROM requisitions r JOIN users u ON u.id=r.requester_id LEFT JOIN work_groups g ON g.id=r.work_group_id WHERE r.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r||(!has_role('approver','supply','admin')&&(int)$r['requester_id']!==(int)$u['id'])){http_response_code(403);exit('ไม่มีสิทธิ์');}$s=db()->prepare('SELECT ri.*,m.code,m.name,m.unit FROM requisition_items ri JOIN materials m ON m.id=ri.material_id WHERE ri.requisition_id=?');$s->execute([$id]);$items=$s->fetchAll();$title=setting('requisition_print_title','ใบเบิกวัสดุสำนักงาน');$subtitle=setting('requisition_print_subtitle','');$header=setting('requisition_print_header_text','');$footer=setting('requisition_print_footer_text','');$showLogo=setting('requisition_print_show_logo','1')==='1'&&setting('logo_path','')!=='';$showStatus=setting('requisition_print_show_status','0')==='1';$labels=['request_no'=>setting('requisition_print_request_no_label','เลขคำขอ'),'date'=>setting('requisition_print_date_label','วันที่'),'requester'=>setting('requisition_print_requester_label','ผู้เบิก'),'group'=>setting('requisition_print_group_label','กลุ่มงาน'),'purpose'=>setting('requisition_print_purpose_label','วัตถุประสงค์'),'item'=>setting('requisition_print_item_label','รหัส/รายการ'),'requested'=>setting('requisition_print_requested_label','ขอ'),'approved'=>setting('requisition_print_approved_label','อนุมัติ'),'issued'=>setting('requisition_print_issued_label','จ่ายแล้ว')];$signers=[setting('requisition_print_sign_requester','ผู้เบิก'),setting('requisition_print_sign_approver','ผู้อนุมัติ'),setting('requisition_print_sign_issuer','ผู้จ่าย'),setting('requisition_print_sign_receiver','ผู้รับ')];render_header($title,false);?><main class="print-sheet request-print-sheet"><div class="print-actions"><button class="btn primary" onclick="print()">พิมพ์ / บันทึก PDF</button></div><header class="request-print-header"><?php if($showLogo):?><?=brand_logo('request-print-logo')?><?php endif;?><h1><?=h($title)?></h1><h2><?=h(setting('office_name',cfg('app.office_name')))?></h2><?php if($subtitle!==''):?><p class="request-print-subtitle"><?=h($subtitle)?></p><?php endif;?></header><?php if($header!==''):?><div class="request-print-note"><?=nl2br(h($header))?></div><?php endif;?><div class="print-meta request-print-meta"><p><b><?=h($labels['request_no'])?>:</b> <?=h($r['request_no'])?></p><p><b><?=h($labels['date'])?>:</b> <?=thai_date($r['submitted_at'])?></p><p><b><?=h($labels['requester'])?>:</b> <?=h($r['full_name'])?></p><p><b><?=h($labels['group'])?>:</b> <?=h($r['group_name']?:'-')?></p><?php if($showStatus):?><p><b>สถานะ:</b> <?=h(status_th($r['status']))?></p><?php endif;?></div><p class="request-print-purpose"><b><?=h($labels['purpose'])?>:</b> <?=nl2br(h($r['purpose']))?></p><div class="table-wrap request-print-table"><table><thead><tr><th><?=h($labels['item'])?></th><th><?=h($labels['requested'])?></th><th><?=h($labels['approved'])?></th><th><?=h($labels['issued'])?></th></tr></thead><tbody><?php foreach($items as$i):?><tr><td><b><?=h($i['code'])?></b> · <?=h($i['name'])?></td><td><?=qty($i['requested_qty']).' '.h($i['unit'])?></td><td><?=is_null($i['approved_qty'])?'-':qty($i['approved_qty'])?></td><td><?=qty($i['issued_qty'])?></td></tr><?php endforeach;?></tbody></table></div><div class="signatures"><?php foreach($signers as$signer):?><div>ลงชื่อ ____________________ <?=h($signer)?><br>(____________________)<br>วันที่ ____/____/____</div><?php endforeach;?></div><?php if($footer!==''):?><footer class="request-print-footer"><?=nl2br(h($footer))?></footer><?php endif;?></main><?php render_footer();exit;}

function executive_dashboard(array$data,bool$full=true):void{
    $s=$data['summary'];$months=['01'=>'ม.ค.','02'=>'ก.พ.','03'=>'มี.ค.','04'=>'เม.ย.','05'=>'พ.ค.','06'=>'มิ.ย.','07'=>'ก.ค.','08'=>'ส.ค.','09'=>'ก.ย.','10'=>'ต.ค.','11'=>'พ.ย.','12'=>'ธ.ค.'];$max=max(1,...array_map(fn($r)=>(int)$r['issue_count'],$data['monthly']));$limit=$full?10:5;?>
    <section class="executive-block"><div class="executive-heading"><div><span class="page-eyebrow">MANAGEMENT INSIGHT</span><h2>Dashboard เชิงบริหาร</h2><p>คำนวณจากจำนวนจ่ายจริง แยกแต่ละวัสดุตามหน่วยพื้นฐาน</p></div><?php if(!$full):?><a class="btn secondary" href="?page=reports&type=executive">ดูรายงานฉบับเต็ม</a><?php endif;?></div>
    <div class="executive-kpis"><article><span>คำขอที่มีการจ่าย</span><strong><?=qty($s['request_count'])?></strong><small>คำขอ</small></article><article><span>ใบจ่าย</span><strong><?=qty($s['issue_count'])?></strong><small>ครั้ง</small></article><article><span>รายการจ่าย</span><strong><?=qty($s['line_count'])?></strong><small>รายการ</small></article><article><span>กลุ่มงานที่ใช้</span><strong><?=qty($s['group_count'])?></strong><small>กลุ่ม</small></article></div>
    <div class="executive-panel"><div class="card-heading"><span class="heading-icon"><?=ui_icon('trend')?></span><div><h2>แนวโน้มการจ่ายรายเดือน</h2><p>จำนวนใบจ่ายในช่วงที่เลือก</p></div></div><div class="trend-chart"><?php foreach($data['monthly']as$row):$parts=explode('-',$row['month_key']);$label=($months[$parts[1]]??$parts[1]).' '.((int)$parts[0]+543);$width=max(4,round((int)$row['issue_count']/$max*100));?><div class="trend-row"><span><?=h($label)?></span><div><i style="width:<?=$width?>%"></i></div><strong><?=qty($row['issue_count'])?></strong></div><?php endforeach;?><?php if(!$data['monthly']):?><p class="empty">ยังไม่มีข้อมูลการจ่ายในช่วงนี้</p><?php endif;?></div></div>
    <div class="executive-grid"><div class="executive-panel"><h3>วัสดุที่ใช้มากที่สุด</h3><div class="table-wrap"><table><thead><tr><th>วัสดุ</th><th>จ่ายจริง</th><th>คำขอ</th></tr></thead><tbody><?php foreach(array_slice($data['materials'],0,$limit)as$row):?><tr><td><b><?=h($row['code'])?></b><br><?=h($row['name'])?></td><td><strong><?=qty($row['issued_qty'])?></strong> <?=h($row['unit'])?></td><td><?=qty($row['request_count'])?></td></tr><?php endforeach;?><?php if(!$data['materials']):?><tr><td colspan="3" class="empty">ไม่มีข้อมูล</td></tr><?php endif;?></tbody></table></div></div>
    <div class="executive-panel"><h3>การใช้งานตามกลุ่มงาน</h3><div class="table-wrap"><table><thead><tr><th>กลุ่มงาน</th><th>คำขอ</th><th>วัสดุที่ใช้</th></tr></thead><tbody><?php foreach(array_slice($data['groups'],0,$limit)as$row):?><tr><td><?=h($row['group_name'])?></td><td><?=qty($row['request_count'])?></td><td><?=qty($row['material_count'])?> รายการ</td></tr><?php endforeach;?><?php if(!$data['groups']):?><tr><td colspan="3" class="empty">ไม่มีข้อมูล</td></tr><?php endif;?></tbody></table></div></div></div>
    <div class="executive-grid"><div class="executive-panel"><h3>การใช้เพิ่มขึ้นผิดปกติ</h3><p class="panel-note">เปรียบเทียบ 30 วันล่าสุดกับ 30 วันก่อนหน้า และแสดงเมื่อเพิ่มอย่างน้อย 50%</p><div class="table-wrap"><table><thead><tr><th>วัสดุ</th><th>30 วันล่าสุด</th><th>ก่อนหน้า</th></tr></thead><tbody><?php foreach(array_slice($data['anomalies'],0,$limit)as$row):?><tr><td><?=h($row['name'])?></td><td><strong><?=qty($row['current_qty'])?></strong> <?=h($row['unit'])?></td><td><?=qty($row['previous_qty'])?></td></tr><?php endforeach;?><?php if(!$data['anomalies']):?><tr><td colspan="3" class="empty">ไม่พบการใช้เพิ่มขึ้นผิดปกติ</td></tr><?php endif;?></tbody></table></div></div>
    <div class="executive-panel"><h3>ประมาณการวัสดุจะหมด</h3><p class="panel-note">คำนวณจากอัตราการจ่ายเฉลี่ย 90 วัน ไม่ใช่การจองหรือคำสั่งซื้อ</p><div class="table-wrap"><table><thead><tr><th>วัสดุ</th><th>คงเหลือ</th><th>ประมาณ</th></tr></thead><tbody><?php foreach(array_slice($data['forecast'],0,$limit)as$row):$days=$row['days_left'];?><tr class="<?=$days!==null&&(float)$days<=30?'forecast-critical':''?>"><td><?=h($row['name'])?></td><td><?=qty($row['stock_qty']).' '.h($row['unit'])?></td><td><?=$days===null?'ข้อมูลไม่พอ':qty($days).' วัน'?></td></tr><?php endforeach;?></tbody></table></div></div></div></section><?php
}

function report_table_v2(string $type): void {
    $from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:'';$material=(int)($_GET['material_id']??0);$requester=(int)($_GET['requester_id']??0);$group=(int)($_GET['group_id']??0);
    if($type==='executive'){$from=$from?:date('Y-m-01',strtotime('-11 months'));$to=$to?:date('Y-m-d');?><form class="executive-filter" method="get"><input type="hidden" name="page" value="reports"><input type="hidden" name="type" value="executive"><label>ตั้งแต่วันที่<input type="date" name="from" value="<?=h($from)?>" required></label><label>ถึงวันที่<input type="date" name="to" value="<?=h($to)?>" required></label><div class="actions"><button class="btn primary">ประมวลผล</button><a class="btn secondary" href="download.php?<?=h(http_build_query(['report'=>'executive','from'=>$from,'to'=>$to]))?>">ส่งออก CSV</a><button class="btn secondary" type="button" onclick="window.print()">พิมพ์ / บันทึก PDF</button></div></form><?php executive_dashboard((new ExecutiveReportService(db()))->build($from,$to),true);return;}
    $materials=db()->query('SELECT id,name FROM materials ORDER BY name')->fetchAll();$users=db()->query('SELECT id,full_name FROM users ORDER BY full_name')->fetchAll();$groups=db()->query('SELECT id,name FROM work_groups ORDER BY name')->fetchAll();
    if(in_array($type,['movements','usage'],true)):?><form class="form-grid" method="get"><input type="hidden" name="page" value="reports"><input type="hidden" name="type" value="<?=h($type)?>"><label>ตั้งแต่วันที่<input type="date" name="from" value="<?=h($from)?>"></label><label>ถึงวันที่<input type="date" name="to" value="<?=h($to)?>"></label><label>วัสดุ<select name="material_id"><option value="0">ทั้งหมด</option><?php foreach($materials as$m):?><option value="<?=$m['id']?>" <?=$material===$m['id']?'selected':''?>><?=h($m['name'])?></option><?php endforeach;?></select></label><?php if($type==='usage'):?><label>ผู้เบิก<select name="requester_id"><option value="0">ทั้งหมด</option><?php foreach($users as$x):?><option value="<?=$x['id']?>" <?=$requester===$x['id']?'selected':''?>><?=h($x['full_name'])?></option><?php endforeach;?></select></label><label>กลุ่มงาน<select name="group_id"><option value="0">ทั้งหมด</option><?php foreach($groups as$g):?><option value="<?=$g['id']?>" <?=$group===$g['id']?'selected':''?>><?=h($g['name'])?></option><?php endforeach;?></select></label><?php endif;?><div class="actions"><button class="btn primary">กรอง</button><a class="btn secondary" href="download.php?<?=h(http_build_query(array_merge($_GET,['report'=>$type])))?>">ส่งออก CSV ตามตัวกรอง</a></div></form><?php endif;
    if($type==='movements'){$where=[];$params=[];if($from){$where[]='DATE(sm.created_at)>=?';$params[]=$from;}if($to){$where[]='DATE(sm.created_at)<=?';$params[]=$to;}if($material){$where[]='sm.material_id=?';$params[]=$material;}$sql='SELECT sm.*,m.name,m.unit,u.full_name FROM stock_movements sm JOIN materials m ON m.id=sm.material_id JOIN users u ON u.id=sm.created_by'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY sm.id DESC LIMIT 1000';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();?><h2>ประวัติการเคลื่อนไหว</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>วันเวลา</th><th>วัสดุ</th><th>ประเภท</th><th>เปลี่ยน</th><th>คงเหลือ</th><th>อ้างอิง</th><th>ผู้บันทึก</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=$r['id']?></td><td><?=thai_date($r['created_at'])?></td><td><?=h($r['name'])?></td><td><?=h($r['movement_type'])?></td><td><?=qty($r['quantity_delta'])?></td><td><?=qty($r['balance_after'])?></td><td><?=h($r['reference_no'])?></td><td><?=h($r['full_name'])?></td></tr><?php endforeach;?></tbody></table></div><?php return;}
    if($type==='usage'){$where=[];$params=[];if($from){$where[]='DATE(r.submitted_at)>=?';$params[]=$from;}if($to){$where[]='DATE(r.submitted_at)<=?';$params[]=$to;}if($material){$where[]='ri.material_id=?';$params[]=$material;}if($requester){$where[]='r.requester_id=?';$params[]=$requester;}if($group){$where[]='r.work_group_id=?';$params[]=$group;}$sql='SELECT r.request_no,r.submitted_at,u.full_name,g.name group_name,m.name,m.unit,ri.requested_qty,ri.approved_qty,ri.issued_qty FROM requisition_items ri JOIN requisitions r ON r.id=ri.requisition_id JOIN users u ON u.id=r.requester_id LEFT JOIN work_groups g ON g.id=r.work_group_id JOIN materials m ON m.id=ri.material_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY r.id DESC LIMIT 1000';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();?><h2>การเบิกแยกรายการ</h2><div class="table-wrap"><table><thead><tr><th>เลขคำขอ</th><th>วันที่</th><th>ผู้เบิก/กลุ่ม</th><th>วัสดุ</th><th>ขอ</th><th>อนุมัติ</th><th>จ่าย</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['request_no'])?></td><td><?=thai_date($r['submitted_at'])?></td><td><?=h($r['full_name'].' / '.$r['group_name'])?></td><td><?=h($r['name'])?></td><td><?=qty($r['requested_qty'])?></td><td><?=qty($r['approved_qty'])?></td><td><?=qty($r['issued_qty']).' '.h($r['unit'])?></td></tr><?php endforeach;?></tbody></table></div><?php return;}
    if($type==='assets'){$rows=db()->query('SELECT aa.*,m.name,m.unit,u.full_name,r.request_no FROM asset_assignments aa JOIN materials m ON m.id=aa.material_id JOIN users u ON u.id=aa.assigned_user_id JOIN requisition_items ri ON ri.id=aa.requisition_item_id JOIN requisitions r ON r.id=ri.requisition_id WHERE aa.quantity>aa.returned_qty ORDER BY aa.assigned_at DESC')->fetchAll();?><a class="btn secondary float-right" href="download.php?report=assets">ส่งออก CSV</a><h2>อุปกรณ์ใช้ซ้ำที่อยู่กับผู้ใช้</h2><div class="table-wrap"><table><thead><tr><th>ผู้รับ</th><th>วัสดุ</th><th>คงค้าง</th><th>คำขอ</th><th>วันที่</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['full_name'])?></td><td><?=h($r['name'])?></td><td><?=qty($r['quantity']-$r['returned_qty']).' '.h($r['unit'])?></td><td><?=h($r['request_no'])?></td><td><?=thai_date($r['assigned_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php return;}
    $sql='SELECT m.*,c.name category_name FROM materials m LEFT JOIN categories c ON c.id=m.category_id'.($type==='low'?' WHERE m.active=1 AND m.stock_qty<=m.minimum_qty':'').' ORDER BY m.name';$rows=db()->query($sql)->fetchAll();?><a class="btn secondary float-right" href="download.php?report=<?=h($type==='low'?'low':'stock')?>">ส่งออก CSV</a><h2><?=$type==='low'?'รายการต่ำกว่ายอดขั้นต่ำ':'ยอดคงเหลือ ณ ปัจจุบัน'?></h2><?php table_materials($rows);
}
